+        .expect("BT40 Shrink 20 mm");
+    let lg = ComponentGeometry::holder(&lib, ADAPTIVE_PORT, lib.gauge_len).expect("draws");
+    let back = HolderShape { gauge_len: lib.gauge_len, nose_d: 33.0, largest_d: 42.0, ..hidden };
